// One exact failed AR20 pose, saved direct anchor, no full-table generation.
#include "slurry_scattering_provider.h"
#include "slurry_spd_table.h"
#include <Eigen/Eigenvalues>
#include <fstream>
#include <sstream>
#include <iostream>
#include <iomanip>
#include <cstdlib>
#include <cctype>
namespace sc=SlurryScattering;namespace gp=SlurryGrandPair;
constexpr double ar=20.,ti=.0049245303592113559,tj=.041010932014513654,az=1.7016960206944713;
std::string readfile(const std::string&path){std::ifstream f(path);if(!f)throw std::runtime_error("Cannot open "+path);std::ostringstream s;s<<f.rdbuf();return s.str();}
double scalar(const std::string&s,const std::string&key){auto i=s.find('"'+key+'"');if(i==std::string::npos)throw std::runtime_error("Missing "+key);i=s.find(':',i);char*end=nullptr;double x=std::strtod(s.c_str()+i+1,&end);if(end==s.c_str()+i+1||!std::isfinite(x))throw std::runtime_error("Invalid "+key);return x;}
sc::Mat17 readmatrix(const std::string&s){auto i=s.find("\"raw_full17\"");if(i==std::string::npos)throw std::runtime_error("Missing raw_full17");i=s.find('[',i);const char*p=s.c_str()+i;sc::Mat17 m;for(int k=0;k<289;++k){while(*p&&(*p=='['||*p==']'||*p==','||std::isspace(static_cast<unsigned char>(*p))))++p;char*end=nullptr;m(k/17,k%17)=std::strtod(p,&end);if(end==p||!std::isfinite(m(k/17,k%17)))throw std::runtime_error("Invalid raw matrix");p=end;}return .5*(m+m.transpose()).eval();}
void geometry_check(const std::string&s){if(std::abs(scalar(s,"aspect_ratio")-ar)>1e-12||std::abs(scalar(s,"theta_i")-ti)>1e-14||std::abs(scalar(s,"theta_j")-tj)>1e-14||std::abs(scalar(s,"phi")-az)>1e-14)throw std::runtime_error("Saved matrix is not the exact failed AR20 pose");}
double rel(const sc::Mat11&a,const sc::Mat11&b){return (a-b).norm()/std::max(b.norm(),1e-300);}
double energy(const sc::Mat11&a,const sc::Mat11&b){Eigen::GeneralizedSelfAdjointEigenSolver<sc::Mat11> e(a,b);if(e.info()!=Eigen::Success)throw std::runtime_error("Energy eigensolve failed");return (e.eigenvalues().array()-1.).abs().maxCoeff();}
struct Check{double force=0,torque=0,stress=0,energy_fd=0;};
Check runtime_check(const sc::Mat11&corr,const std::array<sc::Body,2>&bodies,double h){
 const sc::Vec3 middle(0.,0.,h/2),li=(middle-bodies[0].center)/ar,lj=(middle-bodies[1].center)/ar;const auto p=gp::relative_projection({li.x(),li.y(),li.z()},{lj.x(),lj.y(),lj.z()},gp::SlipConvention::NonaffineMidpoint);
 gp::Mat11 cm{};for(int i=0;i<11;++i)for(int j=0;j<11;++j)cm[11*i+j]=corr(i,j)/ar;gp::Metadata meta;meta.kind=gp::MatrixKind::PairCorrection;meta.model_id="one_pose_matched_test";const auto m=gp::lift_reduced(cm,p,meta);gp::Frame f;f.model_length=f.solver_length=ar;
 gp::Inputs x;for(int k=0;k<12;++k)x.velocity[k]=.1*std::sin(.83*(k+1));Eigen::Matrix<double,5,1> ev;for(int k=0;k<5;++k)ev[k]=.1*std::cos(.57*(k+1));for(int k=0;k<5;++k)for(int j=0;j<9;++j)x.strain[j]+=ev[k]*gp::strain_basis()[k][j]/ar;
 const auto y=gp::evaluate(m,f,x);const auto eb=gp::embed(f,x.background,x.image_nonaffine);const auto z=gp::state(eb,x.velocity,gp::strain_coordinates(x.strain));const auto weighted=gp::multiply(m.resistance,z);Check out;
 for(int k=0;k<3;++k){out.force=std::max(out.force,std::max(std::abs(y.force_i[k]+ar*weighted[k]),std::abs(y.force_j[k]+ar*weighted[6+k])));out.torque=std::max(out.torque,std::max(std::abs(y.torque_i[k]+ar*ar*weighted[3+k]),std::abs(y.torque_j[k]+ar*ar*weighted[9+k])));}
 for(int k=0;k<5;++k)out.stress=std::max(out.stress,std::abs(y.stress_coordinates[k]-ar*ar*weighted[12+k]));
 const double step=1e-5;double scale=std::max(1.,std::abs(y.energy));for(int k=0;k<12;++k){auto xp=x,xm=x;xp.velocity[k]+=step;xm.velocity[k]-=step;const double fd=(gp::evaluate(m,f,xp).energy-gp::evaluate(m,f,xm).energy)/(2*step);out.energy_fd=std::max(out.energy_fd,std::abs(fd-y.gradient[k])/scale);}
 for(int k=0;k<5;++k){auto xp=x,xm=x;for(int j=0;j<9;++j){xp.strain[j]+=step*gp::strain_basis()[k][j]/ar;xm.strain[j]-=step*gp::strain_basis()[k][j]/ar;}const double fd=(gp::evaluate(m,f,xp).energy-gp::evaluate(m,f,xm).energy)/(2*step);out.energy_fd=std::max(out.energy_fd,std::abs(fd-y.stress_coordinates[k]/ar)/scale);}
 out.force/=std::max(1.,corr.norm());out.torque/=std::max(1.,ar*corr.norm());out.stress/=std::max(1.,ar*corr.norm());return out;
}
int main(int argc,char**argv){try{
 if(argc<2)throw std::runtime_error("Usage: check_ar20_matching anchor_probe.json [heldout_probe.json ...]");const auto anchor_text=readfile(argv[1]);geometry_check(anchor_text);const double anchor=scalar(anchor_text,"h_over_c");
 const std::array<sc::Vec3,2> axes{{{std::sin(ti),0.,std::cos(ti)},{std::sin(tj)*std::cos(az),std::sin(tj)*std::sin(az),std::cos(tj)}}};sc::Provider provider;provider.basis.aspect_ratio=ar;provider.hybrid=true;provider.hybrid_version=4;provider.anchor_count=2;provider.anchor_gaps={anchor,2*anchor,0.};SlurrySPDCoordinates::Shape shape(ar);provider.isolated_local=shape.isolated_local;
 const auto ba=sc::geometry(axes,anchor,ar);const sc::Mat11 target=sc::reduced(readmatrix(anchor_text),sc::midpoint_map(ba,anchor,ar)),self=shape.self(axes,anchor),singular=provider.near11(axes,anchor);const sc::Mat11 residual=target-self-singular;sc::AnchorResiduals saved;for(int i=0;i<11;++i)for(int j=0;j<11;++j)saved.values[0][11*i+j]=residual(i,j);
 std::vector<std::pair<double,sc::Mat11>> references;for(int k=2;k<argc;++k){const auto text=readfile(argv[k]);geometry_check(text);const double h=scalar(text,"h_over_c");references.push_back({h,sc::reduced(readmatrix(text),sc::midpoint_map(sc::geometry(axes,h,ar),h,ar))});}
 std::cout<<std::setprecision(17)<<"{\n\"method\":\"ar20_saved_anchor_v4_matching_audit\",\n\"physical_accuracy_qualified\":false,\n\"note\":\"Algebra, passivity, response derivatives and one-node66-entry encoding only; Stokes anchor convergence, missing singular terms, held-out model accuracy and interpolation remain separate gates\",\n\"anchor_gap_over_c\":"<<anchor<<",\n\"queries\":[\n";
 bool pass=true,overlap_pass=true;int overlap_count=0;constexpr double overlap_tolerance=.01;std::vector<double> gaps={anchor,.25,.02,1./150.};for(const auto& r:references){bool present=false;for(double h:gaps)present|=std::abs(h-r.first)<1e-13;if(!present)gaps.push_back(r.first);}
 for(std::size_t index=0;index<gaps.size();++index){const double h=gaps[index];const auto bodies=sc::geometry(axes,h,ar);const sc::Mat11 correction=provider.matched_near11(axes,h,saved),total=shape.self(axes,h)+correction,lead=provider.near11(axes,h);Eigen::SelfAdjointEigenSolver<sc::Mat11> eig(total);if(eig.info()!=Eigen::Success)throw std::runtime_error("Total eigensolve failed");const double minimum=eig.eigenvalues().minCoeff();const bool spd=minimum>0;pass&=spd;const Check runtime=runtime_check(correction,bodies,h);pass&=runtime.energy_fd<1e-7&&runtime.force<1e-12&&runtime.torque<1e-12&&runtime.stress<1e-12;
 std::cout<<(index?",\n":"")<<"{\"h_over_c\":"<<h<<",\"gap_nm\":"<<150*h<<",\"runtime_branch\":\""<<(h>=anchor?"direct_stokes":"matched_near")<<"\",\"matching_evaluation\":\""<<(h>anchor?"upward_continuation_for_overlap_only":"near_formula")<<"\""<<",\"minimum_total11_eigenvalue\":"<<minimum<<",\"total11_spd\":"<<(spd?"true":"false")<<",\"constant_residual_relative_error\":"<<rel(correction-lead,residual)<<",\"force_mapping_scaled_error\":"<<runtime.force<<",\"torque_mapping_scaled_error\":"<<runtime.torque<<",\"stresslet_mapping_scaled_error\":"<<runtime.stress<<",\"runtime_energy_derivative_scaled_error\":"<<runtime.energy_fd;
 if(index==0)std::cout<<",\"anchor_reconstruction_relative_error\":"<<rel(total,target);
 if(spd){const sc::Mat11 m=shape.contact_map(axes,h),mi=SlurrySPDCoordinates::inverse_contact_map(m),pc=mi.transpose()*shape.preconditioner(axes,h,h)*mi;sc::Mat11 d=sc::Mat11::Identity(),di=d;d(2,2)=std::sqrt(pc(2,2));di(2,2)=1/d(2,2);const sc::Mat11 conditioned=di*mi.transpose()*total*mi*di;Eigen::SelfAdjointEigenSolver<sc::Mat11> logs(.5*(conditioned+conditioned.transpose()).eval());if(logs.info()!=Eigen::Success||logs.eigenvalues().minCoeff()<=0)throw std::runtime_error("Conditioned matrix not SPD");const sc::Mat11 logm=logs.eigenvectors()*logs.eigenvalues().array().log().matrix().asDiagonal()*logs.eigenvectors().transpose();std::stringstream storage;storage<<std::setprecision(17);int count=0;for(int i=0;i<11;++i)for(int j=0;j<=i;++j){storage<<logm(i,j)<<' ';++count;}sc::Mat11 decoded;for(int i=0;i<11;++i)for(int j=0;j<=i;++j){double v;if(!(storage>>v))throw std::runtime_error("66-entry decode failed");decoded(i,j)=decoded(j,i)=v;}const sc::Mat11 roundtrip=m.transpose()*d*SlurrySPDTable::symmetric_exp(decoded)*d*m;const double err=energy(roundtrip,total);pass&=err<1e-9&&count==66;std::cout<<",\"encoded_values\":"<<count<<",\"log66_roundtrip_worst_energy_error\":"<<err;}
 for(const auto&r:references)if(std::abs(r.first-h)<1e-13){Eigen::LLT<sc::Mat11> positive(r.second);if(positive.info()!=Eigen::Success)throw std::runtime_error("Held-out reference not SPD");const double error=energy(total,r.second);const bool independent_gap=std::abs(h-anchor)>1e-13;if(independent_gap){++overlap_count;overlap_pass&=error<=overlap_tolerance;}std::cout<<",\"supplied_direct_total11_worst_energy_error\":"<<error<<",\"counts_as_heldout_gap\":"<<(independent_gap?"true":"false")<<",\"model_overlap_tolerance\":"<<overlap_tolerance<<",\"model_overlap_error_gate_passed\":"<<(error<=overlap_tolerance?"true":"false");}
 std::cout<<'}';}
 std::cout<<"\n],\n\"actual_geometry_hardfloor_checks\":[\n";
 const double floor_h=1./150.;const sc::Mat11 floor_correction=provider.matched_near11(axes,floor_h,saved);
 const std::array<double,3> actual_nm{{0.,.5,-.15}};
 for(std::size_t k=0;k<actual_nm.size();++k){const double actual_h=actual_nm[k]/150.;const auto actual_bodies=sc::geometry(axes,actual_h,ar);const auto actual_map=sc::midpoint_map(actual_bodies,actual_h,ar);Eigen::Matrix<double,11,17> projection=Eigen::Matrix<double,11,17>::Zero();projection.topLeftCorner<6,12>()=actual_map;projection.bottomRightCorner<5,5>().setIdentity();const sc::Mat17 actual_total=provider.isolated(actual_bodies)+projection.transpose()*floor_correction*projection;Eigen::SelfAdjointEigenSolver<sc::Mat17> full(actual_total);if(full.info()!=Eigen::Success)throw std::runtime_error("Actual-geometry grand eigensolve failed");Eigen::SelfAdjointEigenSolver<Eigen::Matrix<double,12,12>> velocity(actual_total.topLeftCorner<12,12>());const bool positive=full.eigenvalues().minCoeff()>0.;pass&=positive;const auto runtime=runtime_check(floor_correction,actual_bodies,actual_h);pass&=runtime.energy_fd<1e-7;std::cout<<(k?",\n":"")<<"{\"actual_gap_nm\":"<<actual_nm[k]<<",\"effective_gap_nm\":1,\"scope\":\""<<(actual_nm[k]<0?"overlap_robustness_only_no_overlapping_fluid_BVP":"actual_vs_virtual_geometry_lift")<<"\",\"minimum_full17_eigenvalue\":"<<full.eigenvalues().minCoeff()<<",\"minimum_velocity12_eigenvalue\":"<<velocity.eigenvalues().minCoeff()<<",\"full17_spd\":"<<(positive?"true":"false")<<",\"runtime_energy_derivative_scaled_error\":"<<runtime.energy_fd<<'}';}
 std::cout<<"\n],\n\"algebra_passivity_encoding_gate_passed\":"<<(pass?"true":"false")<<",\n\"heldout_gap_count\":"<<overlap_count<<",\n\"physical_overlap_error_gate_passed\":"<<(overlap_count?(overlap_pass?"true":"false"):"null")<<"\n}\n";return pass&&overlap_pass?0:2;
 }catch(const std::exception&e){std::cerr<<"AR20 matching audit: "<<e.what()<<'\n';return 1;}}
